function easeInOutExpo(x) {
	return x === 0
		? 0
		: x === 1
			? 1
			: x < 0.5 ? Math.pow(2, 20 * x - 10) / 2
				: (2 - Math.pow(2, -20 * x + 10)) / 2;
}

class ShapeShifter {
	constructor(x, y, w) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.timer = 0;
		this.t1 = 72;
		this.t2 = this.t1 + 72;
		this.direction = int(random(4)) * (TAU / 4);
		this.offset = 0;
		this.init();
		this.shape1 = new Shape();
		this.shape2 = new Shape();
	}

	show() {
		push();
		translate(this.x, this.y);
		noStroke();
		fill(0);
		square(0, 0, this.w);
		ctx.clip();
		let x1 = this.offset * cos(this.direction);
		let y1 = this.offset * sin(this.direction);
		let x2 = x1 + this.w * cos(this.direction - PI);
		let y2 = y1 + this.w * sin(this.direction - PI);
		this.shape1.show(x1, y1, this.w);
		this.shape2.show(x2, y2, this.w);
		pop();
	}

	update() {
		this.shiftX = this.x + this.offset * cos(this.direction);
		this.shiftY = this.y + this.offset * sin(this.direction);
		this.timer++;
		if (0 < this.timer && this.timer < this.t1) {
			let n = norm(this.timer, 0, this.t1 - 1);
			this.offset = lerp(0, this.w, easeInOutExpo(n));
		}

		if (this.timer > this.t2) {
			this.init();
		}
	}

	run() {
		this.show();
		this.update();
	}

	init() {
		this.timer = -72 * int(random(5));
		this.direction = int(random(4)) * (TAU / 4);
		this.offset = 0;
		this.shape1 = this.shape2;
		this.shape2 = new Shape();
	}
}

class Shape {
	constructor() {
		this.type = int(random(2));
		this.color1 = this.color2 = 0;
		while (this.color1 == this.color2) {
			this.color1 = random(colors);
			this.color2 = random(colors);
		}
		this.dotsCount = int(random(5) + 1);
		this.checkeredCount = int(random(2, 6));
		this.angle = int(random(4)) * (TAU / 4);
	}

	show(x_, y_, w_) {
		push();
		translate(x_, y_);
		rotate(this.angle);
		noStroke();
		fill(this.color1);
		square(0, 0, w_);
		if (this.type == 0) {
			let area = w_ * 0.8;
			let cellCount = this.dotsCount;
			let cellSize = area / cellCount;
			for (let i = 0; i < cellCount; i++) {
				for (let j = 0; j < cellCount; j++) {
					let x = i * cellSize + (cellSize / 2) - (w_ / 2) + (w_ - area) / 2;
					let y = j * cellSize + (cellSize / 2) - (w_ / 2) + (w_ - area) / 2;
					if ((i + j) % 2 == 0) {
						fill(this.color2);
						circle(x, y, cellSize);
					}
				}
			}
		} else if (this.type == 1) {
			let cellCount = this.checkeredCount;
			let cellSize = w_ / cellCount;
			for (let i = 0; i < cellCount; i++) {
				for (let j = 0; j < cellCount; j++) {
					let x = i * cellSize + (cellSize / 2) - w_ / 2;
					let y = j * cellSize + (cellSize / 2) - w_ / 2;
					if ((i + j) % 2 == 0) {
						fill(this.color2);
						square(x, y, cellSize);
					}
				}
			}
		}
		pop();
	}
}

